import { exec } from '@actions/exec';
/** Wrapper around the GitHub toolkit exec command which returns the output.
 * Also allows you to easily toggle the current working directory.
 * on a non-zero exit status or to leave implementation up to the caller.
 */
export async function execute(cmd, cwd = process.cwd(), args = [], silent = false, ignoreReturnCode = false) {
    const stdout = [];
    const stderr = [];
    const exitCode = await exec(cmd, args, {
        silent,
        cwd,
        listeners: {
            stdout: (data) => {
                stdout.push(data.toString());
            },
            stderr: (data) => {
                stderr.push(data.toString());
            }
        },
        ignoreReturnCode
    });
    return { stdout, stderr, result: exitCode === 0 };
}
