import * as core from '@actions/core';
import deepmerge from 'deepmerge';
import * as fs from 'fs';
import { load as yamlLoad } from 'js-yaml';
import { resolve } from 'path';
import { inspect } from 'util';
/**
 * Reads configuration from the provided config file path.
 * If a configuration is also present in the workspace directory,
 * the function merges the two configurations, with the workspace
 * configuration taking precedence.
 *
 * @param config - Path to the configuration file.
 * @param workspace - Path to the workspace directory.
 * @returns A merged configuration object, or an empty object if no configuration is found.
 */
export function readJSONSync(path) {
    const data = fs.readFileSync(path, 'utf-8');
    const ext = path.split('.').pop()?.toLowerCase();
    if (ext === 'json') {
        return JSON.parse(data);
    }
    else if (ext === 'yaml' || ext === 'yml') {
        return yamlLoad(data);
    }
    else {
        throw new Error(`Unsupported file extension: ${ext}`);
    }
}
/**
 * Custom array merge function to remove duplicates.
 *
 * @param source - Source array.
 * @param target - Target array.
 * @returns Merged array with duplicates removed.
 */
function arrayMergeDedupe(source, target) {
    return Array.from(new Set([...source, ...target]));
}
export function readConfig(defaultOptions, mainConfigPath, workspace, defaultConfigName) {
    const configFile = resolve(mainConfigPath || defaultConfigName);
    const configFilename = configFile.split('/').pop();
    const workspaceConfig = resolve(workspace, configFilename || defaultConfigName);
    const configExists = fs.existsSync(configFile);
    const workspaceConfigExists = workspaceConfig !== configFile && fs.existsSync(workspaceConfig);
    let resultData = defaultOptions || {};
    if (configExists) {
        resultData = deepmerge(resultData, readJSONSync(configFile), { arrayMerge: arrayMergeDedupe });
    }
    if (workspaceConfigExists) {
        resultData = deepmerge(resultData, readJSONSync(workspaceConfig), { arrayMerge: arrayMergeDedupe });
    }
    core.startGroup('🔎 Dotnet Format Config');
    core.info(`${inspect(resultData)}`);
    core.endGroup();
    return resultData;
}
